<?php
declare(strict_types=1);
/** ShahkotPK v11.3.0 — Public + Admin AI Copilot (business microsite URLs updated). */
if(!function_exists('sk1100ai_h')){
function sk1100ai_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sk1100ai_root():string{return dirname(__DIR__);}
function sk1100ai_tid():int{try{if(function_exists('tenant_id'))return (int)tenant_id();if(function_exists('current_tenant')){$t=current_tenant();return (int)($t['id']??0);}}catch(Throwable $e){}return 0;}
function sk1100ai_uid():int{try{$u=function_exists('current_user')?current_user():null;return (int)($u['id']??0);}catch(Throwable $e){return 0;}}
function sk1100ai_table(string $t):bool{static $c=[];if(isset($c[$t]))return $c[$t];try{$q=db()->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? LIMIT 1');$q->execute([$t]);return $c[$t]=(bool)$q->fetchColumn();}catch(Throwable $e){return $c[$t]=false;}}
function sk1100ai_columns(string $t):array{static $c=[];if(isset($c[$t]))return $c[$t];if(!sk1100ai_table($t))return $c[$t]=[];try{$q=db()->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$q->execute([$t]);return $c[$t]=$q->fetchAll(PDO::FETCH_COLUMN)?:[];}catch(Throwable $e){return $c[$t]=[];}}
function sk1100ai_master_key():string{$dir=sk1100ai_root().'/storage/secure';$file=$dir.'/ai-copilot-v1100.key';if(!is_dir($dir))@mkdir($dir,0770,true);if(is_file($file)){$raw=@file_get_contents($file);if(is_string($raw)&&strlen($raw)>=32)return substr($raw,0,32);}try{$key=random_bytes(32);}catch(Throwable $e){$key=hash('sha256',__FILE__.php_uname(),true);}@file_put_contents($file,$key,LOCK_EX);@chmod($file,0600);return $key;}
function sk1100ai_encrypt(string $plain):string{if($plain==='')return '';$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($plain,'aes-256-gcm',sk1100ai_master_key(),OPENSSL_RAW_DATA,$iv,$tag);if($cipher===false)throw new RuntimeException('Could not encrypt API key.');return base64_encode($iv.$tag.$cipher);}
function sk1100ai_decrypt(string $blob):string{if($blob==='')return '';$raw=base64_decode($blob,true);if($raw===false||strlen($raw)<29)return '';$iv=substr($raw,0,12);$tag=substr($raw,12,16);$cipher=substr($raw,28);$plain=openssl_decrypt($cipher,'aes-256-gcm',sk1100ai_master_key(),OPENSSL_RAW_DATA,$iv,$tag);return is_string($plain)?$plain:'';}
function sk1100ai_settings(?int $tid=null):array{$tid=$tid??sk1100ai_tid();$d=['tenant_id'=>$tid,'provider'=>'local','model'=>'gemini-3.7-flash','public_enabled'=>1,'admin_enabled'=>1,'voice_enabled'=>1,'tts_enabled'=>1,'auto_train'=>1,'training_interval_minutes'=>360,'public_system_prompt'=>'You are the ShahkotPK website assistant. Answer from provided website context. If information is not in context, say that clearly.','admin_system_prompt'=>'You are the ShahkotPK Admin Copilot. Explain the admin system and use only the allow-listed commands supplied by the application.'];if(!sk1100ai_table('ai_copilot_settings_v1100'))return $d;try{$q=db()->prepare('SELECT * FROM ai_copilot_settings_v1100 WHERE tenant_id=? LIMIT 1');$q->execute([$tid]);$r=$q->fetch()?:[];return array_merge($d,$r);}catch(Throwable $e){return $d;}}
function sk1100ai_save_settings(array $in,int $uid):void{$tid=sk1100ai_tid();$old=sk1100ai_settings($tid);$provider=in_array(($in['provider']??'local'),['local','gemini_ai_studio'],true)?$in['provider']:'local';$model=trim((string)($in['model']??'gemini-3.7-flash'))?:'gemini-3.7-flash';$secret=(string)($old['api_key_cipher']??'');$new=trim((string)($in['api_key']??''));if($new!=='')$secret=sk1100ai_encrypt($new);$sql='INSERT INTO ai_copilot_settings_v1100(tenant_id,provider,model,api_key_cipher,public_enabled,admin_enabled,voice_enabled,tts_enabled,auto_train,training_interval_minutes,public_system_prompt,admin_system_prompt,updated_by,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE provider=VALUES(provider),model=VALUES(model),api_key_cipher=VALUES(api_key_cipher),public_enabled=VALUES(public_enabled),admin_enabled=VALUES(admin_enabled),voice_enabled=VALUES(voice_enabled),tts_enabled=VALUES(tts_enabled),auto_train=VALUES(auto_train),training_interval_minutes=VALUES(training_interval_minutes),public_system_prompt=VALUES(public_system_prompt),admin_system_prompt=VALUES(admin_system_prompt),updated_by=VALUES(updated_by),updated_at=NOW()';db()->prepare($sql)->execute([$tid,$provider,$model,$secret,!empty($in['public_enabled'])?1:0,!empty($in['admin_enabled'])?1:0,!empty($in['voice_enabled'])?1:0,!empty($in['tts_enabled'])?1:0,!empty($in['auto_train'])?1:0,max(30,min(10080,(int)($in['training_interval_minutes']??360))),mb_substr(trim((string)($in['public_system_prompt']??'')),0,4000),mb_substr(trim((string)($in['admin_system_prompt']??'')),0,4000),$uid]);}
function sk1100ai_version():string{try{return function_exists('setting')?(string)setting('installed_app_version','11.0.0'):'11.0.0';}catch(Throwable $e){return '11.0.0';}}
function sk1100ai_insert_knowledge(int $tid,string $scope,string $type,string $key,string $title,string $content,string $url=''):void{if(trim($content)==='')return;$checksum=hash('sha256',$title."\n".$content."\n".$url);$q=db()->prepare('INSERT INTO ai_knowledge_v1100(tenant_id,scope,source_type,source_key,title,content,url,checksum,indexed_at) VALUES(?,?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title),content=VALUES(content),url=VALUES(url),checksum=VALUES(checksum),indexed_at=NOW()');$q->execute([$tid,$scope,$type,mb_substr($key,0,190),mb_substr($title,0,250),mb_substr(strip_tags($content),0,30000),mb_substr($url,0,700),$checksum]);}
function sk1100ai_row_text(array $r,array $fields):string{$a=[];foreach($fields as $f)if(isset($r[$f])&&$r[$f]!==''&&$r[$f]!==null)$a[]=$f.': '.(is_scalar($r[$f])?(string)$r[$f]:json_encode($r[$f],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));return implode("\n",$a);}
function sk1100ai_rebuild_knowledge(?int $tid=null):array{$tid=$tid??sk1100ai_tid();if(!sk1100ai_table('ai_knowledge_v1100'))throw new RuntimeException('AI knowledge migration is not installed.');$count=0;db()->prepare('DELETE FROM ai_knowledge_v1100 WHERE tenant_id=?')->execute([$tid]);
 $version=sk1100ai_version();sk1100ai_insert_knowledge($tid,'public','system','version','ShahkotPK version','Current installed ShahkotPK version: '.$version,'/');$count++;
 foreach(['public-nav-modules'=>'public','sidebar-modules'=>'admin'] as $dir=>$scope){foreach(glob(__DIR__.'/'.$dir.'/*.json')?:[] as $f){$j=json_decode((string)@file_get_contents($f),true);if(!is_array($j))continue;$rows=isset($j['items'])&&is_array($j['items'])?$j['items']:[$j];foreach($rows as $r){if(!is_array($r))continue;$title=(string)($r['label']??$r['module_key']??$r['nav_key']??basename($f));$url=(string)($r['url']??'');sk1100ai_insert_knowledge($tid,$scope,'module',basename($f).':'.($r['module_key']??$r['nav_key']??$title),$title,sk1100ai_row_text($r,array_keys($r)),$url);$count++;}}}
 if(sk1100ai_table('homepage_sections_v1010'))try{$q=db()->prepare('SELECT section_key,title,subtitle,enabled,sort_order FROM homepage_sections_v1010 WHERE tenant_id=? ORDER BY sort_order');$q->execute([$tid]);foreach($q->fetchAll()?:[] as $r){sk1100ai_insert_knowledge($tid,'public','homepage','section:'.$r['section_key'],(string)$r['title'],sk1100ai_row_text($r,['section_key','title','subtitle','enabled']),'/');$count++;}}catch(Throwable $e){}
 $tables=[
  ['businesses','business','name',['name','description','tagline','address','area','phone','whatsapp','email','status'],'/business-site.php?id='],
  ['store_products','product','title',['title','name','short_description','description','price','sale_price','stock','status'],'/product.php?id='],
  ['city_portal_items','portal','title',['title','summary','description','category','address','content_type','status'],'/discover.php?id='],
  ['news_posts','news','title_en',['title_en','excerpt_en','body_en','status','published_at'],'/news.php?id='],
  ['blog_posts','blog','title_en',['title_en','excerpt_en','body_en','status'],'/blog.php?id='],
  ['local_deals_v1050','deal','title',['title','description','discount_type','discount_value','minimum_spend','starts_at','ends_at','status'],'/deals-v1050.php'],
 ];
 foreach($tables as [$table,$type,$titleField,$fields,$base]){if(!sk1100ai_table($table))continue;$cols=sk1100ai_columns($table);$where=[];$p=[];if($tid>0&&in_array('tenant_id',$cols,true)){$where[]='tenant_id=?';$p[]=$tid;}if(in_array('status',$cols,true))$where[]="status NOT IN ('deleted','disabled','rejected','inactive')";try{$q=db()->prepare('SELECT * FROM `'.$table.'`'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY id DESC LIMIT 250');$q->execute($p);foreach($q->fetchAll()?:[] as $r){$id=(int)($r['id']??0);$title=(string)($r[$titleField]??$r['name']??$type.' #'.$id);sk1100ai_insert_knowledge($tid,'public',$type,$table.':'.$id,$title,sk1100ai_row_text($r,$fields),$base.($base&&str_ends_with($base,'=')?$id:''));$count++;}}catch(Throwable $e){}
 }
 // Admin knowledge: non-secret system configuration and routes only.
 foreach(['installed_app_version','homepage_builder_version','public_navigation_version','sidebar_manager_version','dummy_data_pack_version'] as $key){try{$v=function_exists('setting')?(string)setting($key,''):'';if($v!==''){sk1100ai_insert_knowledge($tid,'admin','setting',$key,$key,$key.' = '.$v,'');$count++;}}catch(Throwable $e){}}
 if(sk1100ai_table('ai_knowledge_meta_v1100'))db()->prepare('INSERT INTO ai_knowledge_meta_v1100(tenant_id,last_built_at,last_version,item_count) VALUES(?,NOW(),?,?) ON DUPLICATE KEY UPDATE last_built_at=NOW(),last_version=VALUES(last_version),item_count=VALUES(item_count)')->execute([$tid,$version,$count]);return ['items'=>$count,'version'=>$version,'tenant_id'=>$tid];}
function sk1100ai_maybe_refresh(int $tid):void{$s=sk1100ai_settings($tid);if(empty($s['auto_train'])||!sk1100ai_table('ai_knowledge_meta_v1100'))return;try{$q=db()->prepare('SELECT * FROM ai_knowledge_meta_v1100 WHERE tenant_id=?');$q->execute([$tid]);$m=$q->fetch()?:[];$mins=max(30,(int)($s['training_interval_minutes']??360));$stale=!$m||strtotime((string)($m['last_built_at']??''))<time()-$mins*60||(string)($m['last_version']??'')!==sk1100ai_version();if($stale)sk1100ai_rebuild_knowledge($tid);}catch(Throwable $e){}}
function sk1100ai_search(string $q,string $scope='public',int $limit=10):array{$tid=sk1100ai_tid();if(!sk1100ai_table('ai_knowledge_v1100'))return [];$clean=mb_strtolower(trim($q));$tokens=array_values(array_unique(array_filter(preg_split('/[^\pL\pN]+/u',$clean)?:[],fn($x)=>mb_strlen($x)>=2)));if(!$tokens)return [];$rows=[];try{$like='%'.str_replace(['%','_'],['\\%','\\_'],$tokens[0]).'%';$st=db()->prepare("SELECT * FROM ai_knowledge_v1100 WHERE tenant_id=? AND scope IN (?, 'public') AND (LOWER(title) LIKE ? OR LOWER(content) LIKE ?) ORDER BY indexed_at DESC LIMIT 80");$st->execute([$tid,$scope,$like,$like]);$rows=$st->fetchAll()?:[];}catch(Throwable $e){return [];}$sc=[];foreach($rows as $r){$hay=mb_strtolower((string)$r['title'].' '.(string)$r['content']);$score=0;foreach($tokens as $t){$score+=substr_count($hay,$t)*2;if(str_contains(mb_strtolower((string)$r['title']),$t))$score+=5;}if($score)$sc[]=['score'=>$score,'row'=>$r];}usort($sc,fn($a,$b)=>$b['score']<=>$a['score']);return array_map(fn($x)=>$x['row'],array_slice($sc,0,$limit));}
function sk1100ai_context(array $rows,int $max=12000):string{$out='';foreach($rows as $r){$part="\n---\nTITLE: ".$r['title']."\nURL: ".($r['url']?:'n/a')."\n".$r['content'];if(strlen($out.$part)>$max)break;$out.=$part;}return trim($out);}
function sk1100ai_local_answer(string $q,array $rows,string $scope):string{if(!$rows)return $scope==='admin'?'I could not find that in the current Admin knowledge index. Try “system status”, “clear cache”, “rebuild knowledge”, or ask about an admin module.':'I could not find verified ShahkotPK information for that question yet. Try a business, product, property, doctor, deal, booking, or local service name.';$first=$rows[0];$ans=(string)$first['title'];$body=preg_replace('/\s+/',' ',(string)$first['content']);$body=mb_strimwidth($body,0,650,'…');$url=(string)($first['url']??'');return $ans."\n\n".$body.($url?"\n\nOpen: ".$url:'');}
function sk1100ai_gemini(string $question,string $system,string $context,array $settings):?string{$key=sk1100ai_decrypt((string)($settings['api_key_cipher']??''));if($key===''||!function_exists('curl_init'))return null;$model=trim((string)($settings['model']??'gemini-3.7-flash'))?:'gemini-3.7-flash';$input=$system."\n\nImportant: Use only the website context below for site facts. Do not invent prices, availability, addresses, policies, or admin actions.\n\nWEBSITE CONTEXT:\n".$context."\n\nUSER:\n".$question;$body=json_encode(['model'=>$model,'input'=>$input],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$ch=curl_init('https://generativelanguage.googleapis.com/v1beta/interactions');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','x-goog-api-key: '.$key],CURLOPT_POSTFIELDS=>$body,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>25]);$raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if(!is_string($raw)||$code<200||$code>=300)return null;$j=json_decode($raw,true);if(!is_array($j))return null;if(!empty($j['output_text'])&&is_string($j['output_text']))return trim($j['output_text']);$parts=[];foreach(($j['steps']??[]) as $step)if(($step['type']??'')==='model_output')foreach(($step['content']??[]) as $c)if(isset($c['text'])&&is_string($c['text']))$parts[]=$c['text'];$t=trim(implode("\n",$parts));return $t!==''?$t:null;}
function sk1100ai_status_text():string{$bits=['Version '.sk1100ai_version(),'PHP '.PHP_VERSION];try{$q=db()->query('SELECT DATABASE()');$bits[]='DB '.((string)$q->fetchColumn()?:'connected');}catch(Throwable $e){$bits[]='DB error';}$root=sk1100ai_root();$free=@disk_free_space($root);if($free!==false)$bits[]='Disk free '.number_format($free/1073741824,1).' GB';return implode(' · ',$bits);}
function sk1100ai_command(string $text,int $uid):?array{$t=mb_strtolower(trim($text));if(in_array($t,['status','system status','server status','/status'],true))return ['ok'=>true,'message'=>sk1100ai_status_text()];if(in_array($t,['rebuild knowledge','train chatbot','retrain chatbot','/rebuild knowledge'],true)){try{$r=sk1100ai_rebuild_knowledge();return ['ok'=>true,'message'=>'AI knowledge rebuilt: '.number_format((int)$r['items']).' indexed items for v'.$r['version'].'.'];}catch(Throwable $e){return ['ok'=>false,'message'=>$e->getMessage()];}}if(in_array($t,['clear cache','clear all cache','/clear cache'],true)){$_SESSION['sk1100ai_pending']=['action'=>'clear_cache','token'=>strtoupper(substr(bin2hex(random_bytes(4)),0,8)),'expires'=>time()+300];$p=$_SESSION['sk1100ai_pending'];return ['ok'=>true,'confirm'=>true,'message'=>'Cache clear is ready. Send: CONFIRM '.$p['token'].' within 5 minutes.'];}if(preg_match('/^confirm\s+([a-f0-9]{8})$/i',trim($text),$m)){ $p=$_SESSION['sk1100ai_pending']??null;if(!$p||time()>(int)($p['expires']??0)||!hash_equals((string)$p['token'],strtoupper($m[1])))return ['ok'=>false,'message'=>'Confirmation token is invalid or expired.'];unset($_SESSION['sk1100ai_pending']);if($p['action']==='clear_cache'){try{$f=__DIR__.'/system_control_v980.php';if(is_file($f))require_once $f;if(function_exists('sk980_clear_all_cache')){$r=sk980_clear_all_cache();return ['ok'=>true,'message'=>'Cache cleared safely: '.number_format((int)($r['files']??0)).' files.'];}return ['ok'=>false,'message'=>'System cache helper is unavailable.'];}catch(Throwable $e){return ['ok'=>false,'message'=>$e->getMessage()];}}}
 if(preg_match('/^(show|hide)\s+menu\s+([a-z0-9_.-]+)$/i',trim($text),$m)){if(!sk1100ai_table('admin_navigation_overrides_v1022'))return ['ok'=>false,'message'=>'Sidebar manager table is unavailable.'];$enabled=strtolower($m[1])==='show'?1:0;$key=$m[2];try{$sql='INSERT INTO admin_navigation_overrides_v1022(module_key,enabled,placement,updated_by,updated_at) VALUES(?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),updated_by=VALUES(updated_by),updated_at=NOW()';db()->prepare($sql)->execute([$key,$enabled,'sidebar',$uid]);return ['ok'=>true,'message'=>($enabled?'Showing ':'Hiding ').$key.' in managed navigation.'];}catch(Throwable $e){return ['ok'=>false,'message'=>$e->getMessage()];}}
 return null;}
function sk1100ai_chat(string $message,string $scope='public'):array{$message=trim($message);if($message===''||mb_strlen($message)>1200)throw new InvalidArgumentException('Please enter a question up to 1200 characters.');$tid=sk1100ai_tid();$s=sk1100ai_settings($tid);if($scope==='admin'){if(empty($s['admin_enabled']))throw new RuntimeException('Admin Copilot is disabled.');$uid=sk1100ai_uid();$cmd=sk1100ai_command($message,$uid);if($cmd){sk1100ai_log($scope,$message,(string)$cmd['message'],$uid);return ['answer'=>$cmd['message'],'mode'=>'command','command'=>$cmd];}}else{if(empty($s['public_enabled']))throw new RuntimeException('Public assistant is disabled.');$uid=sk1100ai_uid();}
 sk1100ai_maybe_refresh($tid);$rows=sk1100ai_search($message,$scope,10);$context=sk1100ai_context($rows);$system=(string)($scope==='admin'?$s['admin_system_prompt']:$s['public_system_prompt']);$answer=null;$mode='local';if(($s['provider']??'local')==='gemini_ai_studio'){$answer=sk1100ai_gemini($message,$system,$context,$s);if($answer)$mode='gemini_ai_studio';}if(!$answer)$answer=sk1100ai_local_answer($message,$rows,$scope);sk1100ai_log($scope,$message,$answer,$uid);return ['answer'=>$answer,'mode'=>$mode,'sources'=>array_values(array_filter(array_map(fn($r)=>['title'=>$r['title'],'url'=>$r['url']],array_slice($rows,0,5)),fn($x)=>$x['title']))];}
function sk1100ai_log(string $scope,string $q,string $a,int $uid):void{if(!sk1100ai_table('ai_chat_messages_v1100'))return;try{db()->prepare('INSERT INTO ai_chat_messages_v1100(tenant_id,user_id,scope,question,answer,created_at) VALUES(?,?,?,?,?,NOW())')->execute([sk1100ai_tid(),$uid?:null,$scope,mb_substr($q,0,1200),mb_substr($a,0,12000)]);}catch(Throwable $e){}}
function sk1100ai_stats():array{$tid=sk1100ai_tid();$out=['knowledge'=>0,'messages'=>0,'last_built'=>''];try{if(sk1100ai_table('ai_knowledge_v1100')){$q=db()->prepare('SELECT COUNT(*) FROM ai_knowledge_v1100 WHERE tenant_id=?');$q->execute([$tid]);$out['knowledge']=(int)$q->fetchColumn();}if(sk1100ai_table('ai_chat_messages_v1100')){$q=db()->prepare('SELECT COUNT(*) FROM ai_chat_messages_v1100 WHERE tenant_id=?');$q->execute([$tid]);$out['messages']=(int)$q->fetchColumn();}if(sk1100ai_table('ai_knowledge_meta_v1100')){$q=db()->prepare('SELECT last_built_at FROM ai_knowledge_meta_v1100 WHERE tenant_id=?');$q->execute([$tid]);$out['last_built']=(string)($q->fetchColumn()?:'');}}catch(Throwable $e){}return $out;}
